// Compares TypeScript work for consumers that infer types from Loculus schemas
// with consumers that import types generated by @loculus/infer.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { inspect } from 'node:util';
import { generate } from '../packages/infer/dist/index.js';
import { profiles as allProfiles, prelude } from './fixtures/index.mjs';

const ids = [
  'scalar-string-basic', 'scalar-string-trim', 'scalar-number-inclusive', 'scalar-boolean',
  'scalar-presence-target-both', 'array-strict', 'array-wrap', 'object-strict', 'object-passthrough',
  'cli-git-clone-full', 'cli-cf-deploy-sparse', 'supplement-rhf-items-10',
];
const copies = Number(process.env.COPIES ?? 20);
const passes = Number(process.env.PASSES ?? 5);
const dir = resolve('bench/generated/infer-types');
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
const literal = value => inspect(value, { depth: null, compact: true, breakLength: Infinity, maxArrayLength: null, maxStringLength: null });
const ordinary = await import(pathToFileURL(resolve('dist/index.js')));
const profiles = ids.map(id => allProfiles.find(profile => profile.id === id));

let schemas = "import * as l from '../../../dist/index.js';\n" + prelude.replace('(value)=>', '(value:string)=>') + '\n';
let inferred = "import type * as l from '../../../dist/index.js';\nimport * as s from './schemas.js';\n";
let generated = "import type * as t from './types.js';\n";
for (let copy = 0; copy < copies; copy++) for (const profile of profiles) {
  const id = `${profile.id.replaceAll('-', '_')}_${copy}`;
  const input = literal(profile.valid[0]);
  const output = literal(new Function('l', `${prelude}\nreturn ${profile.expressions[0]}`)(ordinary)['~standard'].validate(profile.valid[0]).value);
  schemas += `export const ${id}=${profile.expressions[0]};\n`;
  inferred += `export const input_${id}:l.Input<typeof s.${id}>=${input};export const value_${id}:l.Output<typeof s.${id}>=${output};\n`;
  generated += `export const input_${id}:t.${id}Input=${input};export const value_${id}:t.${id}Output=${output};\n`;
}
writeFileSync(`${dir}/schemas.ts`, schemas);
writeFileSync(`${dir}/inferred.ts`, inferred);
writeFileSync(`${dir}/generated.ts`, generated);
writeFileSync(`${dir}/empty.ts`, 'export {};\n');

const extractStart = performance.now();
const { files } = await generate({ cwd: dir, include: ['schemas.ts'], outFile: 'types.ts' });
const extractMs = performance.now() - extractStart;
writeFileSync(files[0].path, files[0].content);
assert.equal(files[0].schemas.length, copies * profiles.length);

const compilerOptions = { strict: true, skipLibCheck: true, noEmit: true, types: [], target: 'ES2022', module: 'NodeNext', moduleResolution: 'NodeNext' };
const variants = {
  'empty file (lib baseline)': 'empty.ts',
  'schemas only': 'schemas.ts',
  'inferred (schemas + l.Input/l.Output)': 'inferred.ts',
  'generated types only': 'generated.ts',
};
const keys = { checkSeconds: 'Check time', instantiations: 'Instantiations', types: 'Types', memoryKiB: 'Memory used' };
const samples = Object.fromEntries(Object.keys(variants).map(name => [name, []]));
for (const [name, file] of Object.entries(variants)) writeFileSync(`${dir}/${file}.json`, JSON.stringify({ compilerOptions, files: [file] }));
for (let pass = 0; pass < passes; pass++) for (const [name, file] of Object.entries(variants)) {
  const start = performance.now();
  const diagnostics = execFileSync(resolve('node_modules/.bin/tsc'), ['-p', `${dir}/${file}.json`, '--extendedDiagnostics'], { encoding: 'utf8', timeout: 120000 });
  const sample = { wallMs: performance.now() - start };
  for (const [key, label] of Object.entries(keys)) {
    const match = diagnostics.match(new RegExp(`^${label}:\\s+([\\d.]+)`, 'm'));
    assert.ok(match, diagnostics);
    sample[key] = Number(match[1]);
  }
  samples[name].push(sample);
}
const median = values => [...values].sort((a, b) => a - b)[Math.floor(values.length / 2)];
const rows = Object.entries(samples).map(([name, list]) => ({
  variant: name,
  ...Object.fromEntries(['instantiations', 'types', 'checkSeconds', 'memoryKiB', 'wallMs'].map(key => [key, median(list.map(sample => sample[key]))])),
}));
const typescript = JSON.parse(readFileSync('node_modules/typescript/package.json', 'utf8')).version;
console.log(`${profiles.length} fixtures x ${copies} copies = ${profiles.length * copies} schemas, TypeScript ${typescript}, median of ${passes} passes`);
console.log(`loculus-infer extraction: ${extractMs.toFixed(0)} ms (single run, includes ts-morph startup)\n`);
console.log('| Variant | Instantiations | Types | Check time (s) | Memory (KiB) | Wall (ms) |');
console.log('| --- | ---: | ---: | ---: | ---: | ---: |');
for (const row of rows) console.log(`| ${row.variant} | ${row.instantiations} | ${row.types} | ${row.checkSeconds.toFixed(2)} | ${row.memoryKiB} | ${row.wallMs.toFixed(0)} |`);
writeFileSync(`${dir}/report.json`, JSON.stringify({ copies, passes, typescript, extractMs, rows }, null, 2) + '\n');
